"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["20486"],{77120(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.valor_categorico_codigo_invalido","status":422,"titulo":"C\xf3digo do valor categ\xf3rico inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.valor_categorico_codigo_invalido","requisitos":[],"oQueAconteceu":["Um item de `valores`, na cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) de um tipo categ\xf3rico, traz um `codigo` que n\xe3o \xe9 aceito. O c\xf3digo \xe9 recusado quando est\xe1 ausente, vazio ou s\xf3 com espa\xe7os; quando passa de 50 caracteres; quando tem o caractere nulo ou texto que n\xe3o \xe9 Unicode v\xe1lido; e quando o texto recebido n\xe3o come\xe7a por letra mai\xfascula de A a Z, cont\xe9m caracteres fora de A a Z, d\xedgitos e sublinhado ou tem sublinhados consecutivos ou no final. Letra min\xfascula e letra acentuada s\xe3o recusadas. Um item `null` na lista chega ao dom\xednio e \xe9 recusado aqui e tamb\xe9m em [r\xf3tulo de valor categ\xf3rico inv\xe1lido](/erros/uniplus.configuracao.tipo_conceito.valor_categorico_rotulo_invalido).","A recusa vem na lista `errors` da resposta, com `field` igual a `valores[i].codigo`, em que `i` \xe9 a posi\xe7\xe3o do item, contada a partir de 0. Cada item com problema gera a pr\xf3pria entrada, e nada \xe9 gravado. A recusa s\xf3 aparece em tipo de natureza `categorico`.","Todo item de `valores` precisa dizer se conta como aprova\xe7\xe3o: o item que omite `contaComoAprovacao` \xe9 recusado no pr\xf3prio campo, com [conta como aprova\xe7\xe3o obrigat\xf3ria](/erros/uniplus.configuracao.tipo_conceito.valor_categorico_conta_como_aprovacao_obrigatoria), junto das recusas de c\xf3digo e de r\xf3tulo do mesmo item. Por isso `valores: [{}]` produz as tr\xeas recusas, uma para cada campo.","Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina."],"comoResolver":["Corrija o c\xf3digo do item indicado em `field`, por exemplo `{ \\"codigo\\": \\"APTO\\", \\"rotulo\\": \\"Apto\\", \\"contaComoAprovacao\\": true }` ou `{ \\"codigo\\": \\"NIVEL_1\\", \\"rotulo\\": \\"N\xedvel 1\\", \\"contaComoAprovacao\\": false }`, sempre com `contaComoAprovacao` declarado, e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);